// Generate unique identifiers and date formats
const now = new Date();
const invDate = now.toLocaleString('en-US', { 
  day: '2-digit', 
  month: 'short', 
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).replace(',', '');

const orderDate = new Date($json.date_created);
