  day: '2-digit', 
  month: 'short', 
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).replace(',', '');

// Generate a GST number (for demo)
const gstNumber = 'AFCD' + Math.floor(10000000 + Math.random() * 90000000) + 'C1ZH';

// Create order ID
const orderId = 'PO' + $json.id.toString().padStart(12, '0');

// Format full address
const shippingAddress = $json.shipping;
let fullAddress = '';
if (shippingAddress.first_name || shippingAddress.last_name) {
  fullAddress += `${shippingAddress.first_name || ''} ${shippingAddress.last_name || ''}`;
}

let addressLine = '';
if (shippingAddress.address_1) {
  addressLine += shippingAddress.address_1;
}
if (shippingAddress.address_2) {
  addressLine += `, ${shippingAddress.address_2}`;
}
if (addressLine) {
  fullAddress += `\n${addressLine}`;
}

let cityStatePostcode = '';
if (shippingAddress.city) {
  cityStatePostcode += shippingAddress.city;
}
if (shippingAddress.state) {
  if (cityStatePostcode) cityStatePostcode += ', ';
  cityStatePostcode += shippingAddress.state;
}
if (shippingAddress.postcode) {
  fullAddress += `\n${cityStatePostcode}, ${shippingAddress.postcode}`;
}
else if (cityStatePostcode) {
  fullAddress += `\n${cityStatePostcode}`;
}

if (shippingAddress.country) {
  fullAddress += `\n${shippingAddress.country}`;
}

const isChilledItem = $json.line_items.some(item => {
  // Check product metadata or categories to determine if it's a cold item
  // This is just a sample condition - replace with your actual logic
  return item.name.toLowerCase().includes('cold') || 
         item.name.toLowerCase().includes('chilled') || 
         item.name.toLowerCase().includes('frozen');
});

const deliveryType = isChilledItem ? 'COLD' : 'NORMAL';
const deliveryMode = $json.shipping_lines && $json.shipping_lines.length > 0 && 
