// Add to daily batch file
const fs = require('fs');
const path = require('path');

// Create today's date in YYYY-MM-DD format
const today = new Date().toISOString().split('T')[0];

// Path to the daily batch file
const batchFilePath = path.join('./shipping_slips', `batch_${today}.txt`);

// Append the file path to the batch file
const pdfPath = `./shipping_slips/${$json.orderId}.pdf`;

try {
  // Make directory if it doesn't exist
  if (!fs.existsSync('./shipping_slips')) {
    fs.mkdirSync('./shipping_slips', { recursive: true });
  }

  // Append to batch file
  fs.appendFileSync(batchFilePath, pdfPath + '\n');

  // Update the order count file
  const countFilePath = path.join('./shipping_slips', `count_${today}.txt`);
  let count = 1;

  if (fs.existsSync(countFilePath)) {
    count = parseInt(fs.readFileSync(countFilePath, 'utf8')) + 1;
  }

  fs.writeFileSync(countFilePath, count.toString());

  return {
    success: true,
    batchFile: batchFilePath,
    totalSlips: count,
    message: `Added order ${$json.orderId} to batch file for ${today}. Total: ${count} slips.`
  };
} catch (error) {
  return {
    success: false,
    error: error.message
  };
}

// This function runs on a scheduled basis (e.g., hourly)
// It checks if it's time to generate the compiled PDF for printing

const fs = require('fs');
const path = require('path');
const { PDFDocument } = require('pdf-lib');

// Get today's date
const today = new Date().toISOString().split('T')[0];
const now = new Date();
const currentHour = now.getHours();

// Define batch processing times (e.g., 12pm, 4pm, and 8pm)
const batchTimes = [12, 16, 20];

// Determine which batch this is
let batchNumber = 0;
for (let i = 0; i < batchTimes.length; i++) {
  if (currentHour < batchTimes[i]) {
    batchNumber = i; // This is the upcoming batch
    break;
  }
  batchNumber = i + 1; // If past all batch times, prepare for next day's first batch
}

// Paths
const batchFilePath = path.join('./shipping_slips', `batch_${today}.txt`);
const compiledPdfPath = path.join('./shipping_slips', `batch_${today}_${batchNumber}.pdf`);

// Check if it's time to process and if we have files to process
if (!fs.existsSync(batchFilePath)) {
  return { status: 'No batch file found' };
}

// Read the batch file to get all PDFs to combine
const pdfPaths = fs.readFileSync(batchFilePath, 'utf8').trim().split('\n');

if (pdfPaths.length === 0) {
  return { status: 'No PDFs to process' };
}

// In a production environment, you would now:
// 1. Combine all PDFs into one using a PDF library
// 2. Send to print server or third-party printing service
// 3. Then clear the batch file after successful printing

// For this example, we'll just simulate the process
return {
  status: 'Batch processing ready',
  batchDate: today,
  batchNumber: batchNumber,
  pdfCount: pdfPaths.length,
  outputPath: compiledPdfPath,
  // In production, add connection details to your printing service
  printService: {
    type: 'thermal_printer',
    model: 'recommended: Zebra ZD621 or Dymo 4XL',
    printCommand: `lp -d PRINTER_NAME -o media=Custom.10x15cm ${compiledPdfPath}`
  }
};
